alter table gov_repo.ict_incidents add column if not exists evidence_ids uuid[] not null default '{}',add column if not exists ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),add column if not exists severity_history jsonb not null default '[]',add column if not exists tags jsonb not null default '[]',add column if not exists external_refs jsonb not null default '{}',add column if not exists closed_by uuid references gov_repo.governance_users(user_id),add column if not exists closed_at timestamptz,add column if not exists closure_rationale text,add column if not exists created_by uuid references gov_repo.governance_users(user_id);
create table gov_repo.ict_incident_timeline(event_id uuid primary key default uuid_generate_v4(),incident_id uuid not null references gov_repo.ict_incidents(incident_id) on delete cascade,event_timestamp timestamptz not null,event_type varchar(50) not null check(event_type in ('occurrence','detection','notification','triage','escalation','containment','eradication','recovery','regulatory_report','client_communication','workaround','permanent_fix','monitoring','closure','evidence_collected','rca_milestone','other')),event_description text not null,actor_user_id uuid references gov_repo.governance_users(user_id),actor_system varchar(255),is_key_milestone boolean not null default false,reporting_phase gov_repo.dora_reporting_phase,report_ref varchar(100),evidence_id uuid references gov_repo.evidence(evidence_id),metadata jsonb not null default '{}',organisation_id uuid not null references gov_repo.organisations(organisation_id),created_at timestamptz not null default now(),constraint ict_timeline_event_actor_check check(actor_user_id is not null or actor_system is not null));
create index idx_ict_timeline_incident on gov_repo.ict_incident_timeline(incident_id,event_timestamp asc);create index idx_ict_timeline_org on gov_repo.ict_incident_timeline(organisation_id);create index idx_ict_timeline_milestones on gov_repo.ict_incident_timeline(incident_id) where is_key_milestone=true;create index idx_ict_timeline_regulatory on gov_repo.ict_incident_timeline(incident_id) where reporting_phase is not null;create index idx_ict_timeline_type on gov_repo.ict_incident_timeline(event_type);alter table gov_repo.ict_incident_timeline enable row level security;create policy "Service role full access ict_incident_timeline" on gov_repo.ict_incident_timeline for all to service_role using(true) with check(true);create policy "Org-scoped read ict_incident_timeline" on gov_repo.ict_incident_timeline for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
create table gov_repo.ict_incident_notifications(notification_id uuid primary key default uuid_generate_v4(),incident_id uuid not null references gov_repo.ict_incidents(incident_id) on delete cascade,reporting_phase gov_repo.dora_reporting_phase not null,authority_name varchar(100) not null,authority_country char(2),authority_case_ref varchar(100),deadline timestamptz not null,submitted_at timestamptz,is_breached boolean not null generated always as (submitted_at is null or submitted_at>deadline) stored,breach_explanation text,report_summary text not null,report_template_version varchar(20),report_evidence_id uuid references gov_repo.evidence(evidence_id),submission_channel varchar(50) not null default 'secure_portal' check(submission_channel in ('secure_portal','encrypted_email','api','physical','other')),confirmation_ref varchar(100),acknowledged_at timestamptz,authority_response text,authority_response_at timestamptz,requires_followup boolean not null default false,followup_deadline timestamptz,followup_completed_at timestamptz,submitted_by uuid references gov_repo.governance_users(user_id),reviewed_by uuid references gov_repo.governance_users(user_id),qes_signature_id uuid references gov_repo.qes_signatures(signature_id),ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence),organisation_id uuid not null references gov_repo.organisations(organisation_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint ict_notif_unique unique(incident_id,reporting_phase,authority_name),constraint ict_notif_breach_explanation check(not is_breached or breach_explanation is not null));
create index idx_ict_notif_incident on gov_repo.ict_incident_notifications(incident_id);create index idx_ict_notif_phase on gov_repo.ict_incident_notifications(reporting_phase);create index idx_ict_notif_deadline on gov_repo.ict_incident_notifications(deadline) where submitted_at is null;create index idx_ict_notif_breached on gov_repo.ict_incident_notifications(organisation_id) where is_breached=true;create index idx_ict_notif_org on gov_repo.ict_incident_notifications(organisation_id);;
